var _imgSrc="images";function initForm(){getCurrentUser();var viewId=getParameterByName("viewId"),assetId=getParameterByName("assetId"),printRequestType=getParameterByName("printType"),propertyValue=getParameterByName("propertyValue");if(printRequestType!=undefined&&printRequestType!==null)printRequestType=parseInt(printRequestType,10);else printRequestType=PRINT_CURRENT;if(viewId!==null&&viewId!=="")if(assetId!==null&&assetId!=="")switch(printRequestType){case PRINT_CURRENT:buildPrintableView(viewId,assetId);break;case PRINT_HISTORY:buildPrintableHistory(viewId,assetId);break;case PRINT_RELATED:buildPrintableRelated(assetId,propertyValue);break;default:buildPrintableView(viewId,assetId);break}}function buildPrintableRelated(assetId,propertyValue){$("#header").html(createHeader("XDB Related Asset Report"));var assetName=asset_GetName(assetId);$("#subHeader").html(createSubHeader("Related Items",assetName,USER_CURRENT.Id));var html=relatedItems_GetHtml(USER_CURRENT.Id,assetId,propertyValue,_imgSrc),finalHtml=[];if(html!==null)$.each(html,function(index,item){finalHtml.push(item)});$("#content").html(finalHtml.join(""));$("#footer").html(createFooter());window.print()}function buildPrintableHistory(viewId,assetId){var view=view_Get(viewId,USER_CURRENT.Id),asset=asset_Get(assetId,USER_CURRENT.Id,viewId);$("#header").html(createHeader("XDB Asset History Report"));$("#subHeader").html(createSubHeader(view.DisplayValue,asset.Name,USER_CURRENT.Id));var historyString="";historyString="<table>"+getHistory(assetId,viewId,true)+"</table>";$("#content").html(historyString);$("#footer").html(createFooter());window.print()}function getHistory(assetId,viewId,boolOrder){retVal="";alphaSortLastPropertName="";$.each(historicalValues_Get(assetId,viewId,boolOrder),function(index,item){if(boolOrder==true)retVal+="<tr><td>"+item.CreationInfo+"</td><td>"+item.PropertyName+"</td><td>"+item.PropertyValue+"</td></tr>";else{var propName=alphaSortLastPropertName==item.PropertyName?"":item.PropertyName;retVal+="<tr><td>"+propName+"</td><td>"+item.PropertyValue+"</td><td>"+item.CreationInfo+"</td></tr>";alphaSortLastPropertName=item.PropertyName}});retVal="<table width='100%'>"+retVal+"</table>";return retVal}function buildPrintableView(viewId,assetId){var view=view_Get(viewId,USER_CURRENT.Id),asset=asset_Get(assetId,USER_CURRENT.Id,viewId),propertyValues,queryString="?assetId="+assetId+"&viewId="+viewId+"&includeUnapproved=false";$.ajax({type:"GET",contentType:"json",dataType:"json",url:SVC_PROPERTYVALUES_GETFORASSET+queryString,processData:false,async:false,error:function(XMLHttpRequest,textStatus,errorThrown){alert(textStatus+" "+errorThrown)},success:function(data){propertyValues=data}});if(view!==null&&propertyValues!==null){$("#header").html(createHeader("XDB Asset Report"));var assetRequestType=ART_DEFINITION;if(view.IsInstance)assetRequestType=ART_INSTANCE;var lbl=assetType_GetReportingLabel(view.AssetTypeId,assetRequestType);$("#subHeader").html(createSubHeader(lbl,asset.Name,USER_CURRENT.Id));var contentHtml="";$.each(view.PropertyGroups,function(index,propertyGroup){contentHtml+=printPropertyGroup(propertyGroup,propertyValues);contentHtml+="<br/>"});$("#content").html(contentHtml);$("#footer").html(createFooter());window.print()}else{}}function createHeader(headerText){var html="<table><tr>";html+='<td><img src="images/xdbPrint.png" alt="XDB Logo" /></td>';html+="<td><h1>"+headerText+"</h1></td>";html+="</tr></table>";return html}function createFooter(){var currentTime=new Date(),month=currentTime.getMonth()+1;switch(month){case 1:month="Jan";break;case 2:month="Feb";break;case 3:month="Mar";break;case 4:month="Apr";break;case 5:month="May";break;case 6:month="Jun";break;case 7:month="Jul";break;case 8:month="Aug";break;case 9:month="Sep";break;case 10:month="Oct";break;case 11:month="Nov";break;case 12:month="Dec";break}var day=currentTime.getDate(),year=currentTime.getFullYear();return day+"-"+month+"-"+year}function getPropertyValue(propertyValues,propertyId){var data=null;$.each(propertyValues,function(index,pv){if(pv.PropertyId==propertyId){data=pv;return false}});return data}function createSubHeader(viewName,assetName,userId){return"<b>"+viewName+" - "+assetName+"</b><br/>"}function printPropertyGroup(propertyGroup,propertyValues){var html=[];html.push("<table><tr><td colspan=2><b>"+propertyGroup.DisplayValue+"</b></td></tr>");$.each(propertyGroup.Properties,function(index,property){var propVal=getPropertyValue(propertyValues,property.Id);if(propVal!==null&&propVal!=undefined){var valToPrint=propVal.DisplayValue;if(valToPrint==null||valToPrint=="")valToPrint=propVal.Value;if(property.DataType==DATA_TYPE_DOCUMENT){var url=SVC_IMAGE_GET_THUMBNAIL+"?imageId="+propVal.Value+"&createThumbnail=false&maxSize=0";valToPrint='<a href="'+url+'">'+valToPrint+"</a>"}html.push("<tr><td>"+property.DisplayValue+"</td><td>"+valToPrint+"</td></tr>")}else html.push("<tr><td>"+property.DisplayValue+"</td><td></td></tr>")});html.push("</table>");return html.join("")}